{
  "missionStatement": "Synthesize existing repository research and online study into a comprehensive chemistry and physics framework for discovering and manufacturing room-temperature superconducting compounds, updating the proposed_chemistry_physics.md and related documents.",
  "criteria": [
    {
      "description": "Perform targeted web searches on key superconductor families (hydrides, nickelates, cuprates, etc.) and document findings with citations in docs/online_research_summary.md.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Update proposed_chemistry_physics.md to include a unified theoretical model (e.g., BCS, Eliashberg, novel mechanisms) with references to primary literature.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Add a section to proposed_chemistry_physics.md on candidate material selection criteria based on electronic structure, lattice dynamics, and known high-Tc families.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Add a section to proposed_chemistry_physics.md on synthesis methods (high-pressure, doping, thin-film) with practical considerations for room-temperature compounds.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Add a section to proposed_chemistry_physics.md on characterization techniques (resistivity, magnetic susceptibility, specific heat) and how they confirm superconductivity.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Add a section to proposed_chemistry_physics.md on manufacturing scalability challenges and potential routes (e.g., alternative synthesis, stabilization at ambient pressure).",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Update roadmap.md to include milestones for experimental validation of the proposed compounds and manufacturing scale-up.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Ensure all new content in proposed_chemistry_physics.md includes inline citations with URLs or DOIs from the online research.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    }
  ]
}

{
  "missionStatement": "Study superconducting materials via online research and synthesize a comprehensive chemistry and physics framework for discovering and manufacturing room-temperature superconducting compounds, updating the repository's documentation and computational tools accordingly.",
  "criteria": [
    {
      "description": "Perform targeted web searches on superconductor families (hydrides, nickelates, etc.) and document findings in docs/online_research_summary.md with citations and data points.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Update proposed_chemistry_physics.md with a unified theoretical model (BCS, Eliashberg, novel mechanisms) and practical synthesis/manufacturing pathways, including candidate selection criteria, synthesis methods, characterization techniques, and scalability considerations, all with inline citations.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Update candidate_materials.md with at least five new candidate compounds (chemical formulas, predicted Tc, crystal structure, synthesis conditions) from literature and online research.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Update synthesis_methods.md with detailed protocols for high-pressure synthesis (e.g., diamond anvil cell, laser-heated), doping techniques, and thin-film deposition methods relevant to room-temperature superconductors.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Update characterization_techniques.md with standard methods (resistivity, magnetic susceptibility, specific heat) and specific protocols for high-pressure samples to confirm superconductivity.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Update theoretical_framework.md to incorporate the latest theoretical models (e.g., hydride superconductivity, nickelate superconductors, exciton-mediated mechanisms) with citations to primary sources.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Update discovery_strategy.md with a systematic screening approach combining DFT calculations, machine learning predictions, and experimental validation, prioritizing high-pressure superhydrides and nickelates.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Update experimental_feedback_loop.md with a closed-loop design for iterative optimization of synthesis parameters and material properties, including success/failure criteria.",
      "expectedFiles": ["experimental_feedback_loop.md"]
    },
    {
      "description": "Update literature_review.md with at least five recent (2020+) peer-reviewed papers on room-temperature superconductivity, including hydrides, nickelates, and other candidate systems, with brief annotations.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Update roadmap.md with milestones for the next two years, covering computational screening, synthesis, characterization, and scalability phases.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Update docs/manufacturing_scalability.md with a detailed plan for scaling up synthesis of promising candidates, including cost analysis, infrastructure requirements, and potential routes for stabilization at ambient pressure.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Update dft_calculator.py with support for new functionals (e.g., SCAN, HSE06) and corrections for hydride systems, and add functions to compute electron-phonon coupling or Tc for candidate structures; ensure corresponding tests pass.",
      "expectedFiles": ["dft_calculator.py", "tests/test_dft_calculator.py"]
    },
    {
      "description": "Update scripts/predict_tc.py with a machine learning model trained on the updated superconductor database, achieving >90% accuracy on a held-out test set.",
      "expectedFiles": ["scripts/predict_tc.py", "tests/test_predict_tc.py"]
    },
    {
      "description": "Update data/superconductor_database.json with at least ten new entries from recent literature, including Tc, pressure, composition, and reference DOI.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Update run_pipeline.py to include a new module for fetching and parsing online research data (e.g., from arXiv or materials databases) to automatically update the candidate list.",
      "expectedFiles": ["run_pipeline.py"]
    },
    {
      "description": "Ensure all updated documents include inline citations to specific papers with URLs or DOIs, and add a references section to the main README.md linking to the most impactful sources.",
      "expectedFiles": ["README.md"]
    }
  ]
}

